def process_order(items, customer, discount_code=None):
    total = 0
    for item in items:
        total += item['price'] * item['quantity']
    if discount_code == 'SAVE10':
        total *= 0.9
    elif discount_code == 'SAVE20':
        total *= 0.8
    tax = total * 0.1
    total += tax
    if total > 100:
        shipping = 0
    else:
        shipping = 10
    total += shipping
    order = {'customer': customer, 'items': items, 'subtotal': total - tax - shipping, 'tax': tax, 'shipping': shipping, 'total': total}
    return order

